package com.viki.voicestudio;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.media.*;import android.graphics.Color;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
public class MainActivity extends Activity {
 JSONArray phrases; int index=0; MediaRecorder recorder; MediaPlayer player; boolean recording=false; TextView title,phrase,status,progress; Button record,play; File dir; static final int MIC=11,EXPORT=12;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(49,65,99));try{InputStream in=getAssets().open("phrases.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();phrases=new JSONArray(out.toString("UTF-8"));}catch(Exception e){new AlertDialog.Builder(this).setMessage(e.toString()).show();return;}dir=new File(getFilesDir(),"recordings");dir.mkdirs();render();}
 String id(){return phrases.optJSONObject(index).optString("id");} File file(){return new File(dir,id()+".m4a");}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(32,43,62));v.setPadding(8,14,8,14);return v;}
 Button button(String s,LinearLayout l,Runnable run){Button b=new Button(this);b.setText(s);l.addView(b);b.setOnClickListener(v->run.run());return b;}
 void render(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,30,24,16);l.setBackgroundColor(Color.rgb(248,249,253));ScrollView sc=new ScrollView(this);sc.addView(l);setContentView(sc);
 title=text("🎙 Студия озвучки Вики",23);l.addView(title);int count=0;for(int i=0;i<phrases.length();i++)if(new File(dir,phrases.optJSONObject(i).optString("id")+".m4a").exists())count++;progress=text("Записано: "+count+" из "+phrases.length()+"     •     Реплика "+(index+1),16);l.addView(progress);
 phrase=text(phrases.optJSONObject(index).optString("text"),22);phrase.setMinHeight(180);l.addView(phrase);status=text(id()+".m4a  •  "+(file().exists()?"✅ Записано":"○ Не записано"),15);l.addView(status);
 record=button("🔴 Начать запись",l,()->{if(recording)stopRecording();else startRecording();});play=button("▶ Прослушать",l,()->play());play.setEnabled(file().exists());
 LinearLayout nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);l.addView(nav);button("← Назад",nav,()->move(-1));button("Далее →",nav,()->move(1));button("Перейти к реплике…",l,()->choose());button("📦 Экспорт ZIP",l,()->export());l.addView(text("Файлы сохраняются на устройстве. Экспорт создаёт ZIP с M4A-записями и текстами реплик.",14));}
 void move(int delta){if(recording)stopRecording();stopPlay();index=Math.max(0,Math.min(phrases.length()-1,index+delta));render();}
 void choose(){String[] labels=new String[phrases.length()];for(int i=0;i<labels.length;i++)labels[i]=(new File(dir,phrases.optJSONObject(i).optString("id")+".m4a").exists()?"✓ ":"○ ")+phrases.optJSONObject(i).optString("id");new AlertDialog.Builder(this).setTitle("Выберите реплику").setItems(labels,(d,w)->{if(recording)stopRecording();stopPlay();index=w;render();}).show();}
 void startRecording(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},MIC);return;}stopPlay();try{recorder=new MediaRecorder();recorder.setAudioSource(MediaRecorder.AudioSource.MIC);recorder.setOutputFormat(MediaRecorder.OutputFormat.MPEG_4);recorder.setAudioEncoder(MediaRecorder.AudioEncoder.AAC);recorder.setAudioEncodingBitRate(128000);recorder.setAudioSamplingRate(44100);recorder.setOutputFile(file().getAbsolutePath());recorder.prepare();recorder.start();recording=true;record.setText("■ Завершить запись");status.setText("● Идёт запись…");play.setEnabled(false);}catch(Exception e){toast("Ошибка микрофона: "+e.getMessage());releaseRecorder();}}
 void stopRecording(){try{recorder.stop();}catch(Exception e){file().delete();toast("Слишком короткая запись — повторите");}releaseRecorder();recording=false;render();}
 void releaseRecorder(){if(recorder!=null){try{recorder.reset();recorder.release();}catch(Exception ignored){}recorder=null;}}
 void stopPlay(){if(player!=null){try{player.release();}catch(Exception ignored){}player=null;}}
 void play(){if(!file().exists())return;stopPlay();try{player=new MediaPlayer();player.setDataSource(file().getAbsolutePath());player.prepare();player.start();player.setOnCompletionListener(mp->stopPlay());}catch(Exception e){toast("Не удалось воспроизвести запись");}}
 void export(){if(recording)stopRecording();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.addCategory(Intent.CATEGORY_OPENABLE);i.putExtra(Intent.EXTRA_TITLE,"Viki_Red_Riding_Hood_Voices.zip");startActivityForResult(i,EXPORT);}
 protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req==EXPORT&&res==RESULT_OK&&data!=null){try(OutputStream output=getContentResolver().openOutputStream(data.getData());ZipOutputStream zip=new ZipOutputStream(output)){int count=0;for(int i=0;i<phrases.length();i++){File f=new File(dir,phrases.optJSONObject(i).optString("id")+".m4a");if(!f.exists())continue;zip.putNextEntry(new ZipEntry(f.getName()));try(InputStream in=new FileInputStream(f)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)zip.write(b,0,n);}zip.closeEntry();count++;}zip.putNextEntry(new ZipEntry("phrases.json"));zip.write(phrases.toString(2).getBytes("UTF-8"));zip.closeEntry();toast("Экспортировано записей: "+count);}catch(Exception e){toast("Ошибка экспорта: "+e.getMessage());}}}
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==MIC&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)startRecording();}
 void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 protected void onPause(){super.onPause();if(recording)stopRecording();stopPlay();}
}